   3: import (
   4: 	"time"
   5: 
   6: 	"github.com/Lokee86/space-rocks/services/game-server/internal/constants"
   7: 	"github.com/Lokee86/space-rocks/services/game-server/internal/rooms"
   8: )
   9: 
  10: func tickSessionGameplayLifecycle(session *webSocketSession, done <-chan struct{}) {
  11: 	ticker := time.NewTicker(time.Second / time.Duration(constants.ServerTickRate))
  12: 	defer ticker.Stop()
  13: 
  14: 	for {
  15: 		select {
  16: 		case <-done:
  17: 			return
  18: 		case <-ticker.C:
  19: 			context := session.sessionContext()
  20: 			if context.Room == nil || context.GamePlayerID == "" {
  21: 				continue
  22: 			}
  23: 
  24: 			if rooms.TickRoomGameOverLifecycle(context.Room, BroadcastRoomSnapshot) {
  25: 				rooms.ReportResolvedMatchResultOnce(context.Room, session.matchResultReporter)
  26: 			}
  27: 		}
  28: 	}
  29: }
===== services/game-server/internal/networking/websocket_outbound_queue.go =====
   1: package networking
   2: 
   3: import (
   4: 	"github.com/Lokee86/space-rocks/services/game-server/internal/logging"
   5: 	observability "github.com/Lokee86/space-rocks/shared/go/observabilityevent"
   6: )
   7: 
   8: func (session *webSocketSession) enqueue(payload []byte) {
   9: 	select {
  10: 	case session.outbound <- payload:
  11: 		return
  12: 	default:
  13: 		session.outboundOverflowOnce.Do(func() {
  14: 			context := session.sessionContext()
  15: 			logging.Emit(observability.Request{
  16: 				Event: observability.EventNameGameServerClientDisconnected,
  17: 				Context: observability.Context{
  18: 					TraceID:   session.connectionTraceID,
  19: 					SessionID: session.sessionID,
  20: 					RoomID:    context.RoomID,
  21: 					PlayerID:  context.GamePlayerID,
  22: 				},
  23: 				Fields: observability.Fields{
  24: 					"reason_code":  "outbound_queue_full",
  25: 					"failure_mode": "outbound_queue_full",
  26: 				},
  27: 			})
  28: 			if session.conn != nil {
  29: 				_ = session.conn.Close()
  30: 			}
  31: 		})
  32: 	}
  33: }
===== services/game-server/internal/networking/resync_write.go =====
   1: package networking
   2: 
   3: import (
   4: 	"encoding/json"
   5: 
   6: 	"github.com/Lokee86/space-rocks/services/game-server/internal/networking/outbound"
   7: 	"github.com/Lokee86/space-rocks/services/game-server/internal/protocol/realtime"
   8: )
   9: 
  10: var writeResyncMessage = outbound.WriteServerMessage
  11: 
  12: func writeResyncRequiredAndApply(session *webSocketSession, queued queuedResyncRequest, remoteAddr string) bool {
  13: 	if session == nil {
  14: 		return true
  15: 	}
  16: 	context := session.sessionContext()
  17: 	if context.Room == nil || context.GamePlayerID == "" {
  18: 		return true
  19: 	}
  20: 	gameplayContext := context.Room.GameplayContext()
  21: 	if !realtime.IsBaselineLane(queued.Request.Lane) || gameplayContext.Game == nil || queued.RoomID != context.RoomID || queued.ReceiverID != context.GamePlayerID || queued.MatchID == "" || queued.Request.MatchID == "" || queued.Request.MatchID != queued.MatchID {
  22: 		return true
  23: 	}
  24: 	matchID := gameplayContext.MatchID
  25: 	if queued.Request.MatchID != matchID {
  26: 		return true
  27: 	}
  28: 	resetRealtimeStateForContext(session, context, matchID)
  29: 	message, err := json.Marshal(map[string]any{
  30: 		"type":        realtime.PacketFamilyResyncRequired,
  31: 		"match_id":    matchID,
  32: 		"lane":        queued.Request.Lane,
  33: 		"baseline_id": queued.Request.BaselineID,
  34: 		"sequence":    queued.Request.Sequence,
  35: 		"reason":      queued.Request.Reason,
  36: 	})
  37: 	if err != nil || !session.sessionContextMatches(context) || !context.Room.GameplayContextMatches(gameplayContext) {
  38: 		return err == nil
  39: 	}
  40: 	if !writeResyncMessage(session.conn, message, func(err error) {
  41: 		logWebSocketWriteClose(err, session.connectionTraceID, session.sessionID, context.RoomID, context.GamePlayerID)
  42: 	}) {
  43: 		return false
  44: 	}
  45: 	if !session.sessionContextMatches(context) || !context.Room.GameplayContextMatches(gameplayContext) {
  46: 		return true
  47: 	}
  48: 	return session.realtimeState.RequireFullBaseline(queued.Request.Lane)
  49: }
===== services/game-server/internal/game/presentation_snapshot.go =====
   1: package game
   2: 
   3: import (
   4: 	"time"
   5: 
   6: 	"github.com/Lokee86/space-rocks/services/game-server/internal/game/runtime"
   7: )
   8: 
   9: // gameplayPresentationFrame is immutable after publication and may be read after game.mu is released.
  10: type gameplayPresentationFrame struct {
  11: 	players         map[string]runtime.ShipState
  12: 	playerSessions  map[string]PlayerSessionState
  13: 	playerLifecycle map[string]string
  14: 	bullets         map[string]runtime.BulletState
  15: 	asteroids       map[string]runtime.AsteroidState
  16: 	pickups         map[string]runtime.PickupState
  17: 	totalAsteroids  int
  18: 	serverSentMsec  int
  19: 	generation      uint64
  20: }
  21: 
  22: func (game *Game) publishPresentationFrameLocked() {
  23: 	players := make(map[string]runtime.ShipState, len(game.entities.Players))
  24: 	for id, player := range game.entities.Players {
  25: 		state := player.State()
  26: 		if session := game.playerSessions[id]; session != nil {
  27: 			state.TeamID = string(session.TeamID)
  28: 		}
  29: 		players[id] = state
  30: 	}
  31: 
  32: 	matchDecision := game.matchDecisionLocked()
  33: 	playerLifecycle := make(map[string]string, len(matchDecision.Players))
  34: 	for _, player := range matchDecision.Players {
  35: 		playerLifecycle[player.ID] = string(player.Status)
  36: 	}
  37: 
  38: 	asteroids := make(map[string]runtime.AsteroidState, len(game.entities.Asteroids))
  39: 	for id, asteroid := range game.entities.Asteroids {
  40: 		asteroids[id] = asteroid.State()
  41: 	}
  42: 
  43: 	bullets := make(map[string]runtime.BulletState, len(game.entities.Projectiles))
  44: 	for id, bullet := range game.entities.Projectiles {
  45: 		bullets[id] = bullet.State()
  46: 	}
  47: 
  48: 	generation := uint64(1)
  49: 	if game.presentationFrame != nil {
  50: 		generation = game.presentationFrame.generation + 1
  51: 	}
  52: 
  53: 	game.presentationFrame = &gameplayPresentationFrame{
  54: 		players:         players,
  55: 		playerSessions:  game.playerSessionStatesLocked(),
  56: 		playerLifecycle: playerLifecycle,
  57: 		bullets:         bullets,
  58: 		asteroids:       asteroids,
  59: 		pickups:         game.pickupStatesLocked(),
  60: 		totalAsteroids:  game.spawner.TotalAsteroidsSpawned(),
  61: 		serverSentMsec:  int(time.Now().UnixMilli()),
  62: 		generation:      generation,
  63: 	}
  64: }
  65: 
  66: // GameplayPresentationSnapshot is the game-facing DTO for realtime presentation projection.
  67: type GameplayPresentationSnapshot struct {
  68: 	SelfID          string
  69: 	Lives           int
  70: 	Players         map[string]runtime.ShipState
  71: 	PlayerSessions  map[string]PlayerSessionState
  72: 	PlayerLifecycle map[string]string
  73: 	Bullets         map[string]runtime.BulletState
  74: 	Asteroids       map[string]runtime.AsteroidState
  75: 	Pickups         map[string]runtime.PickupState
  76: 	TotalAsteroids  int
  77: 	PendingEvents   []PendingPresentationEvent
  78: 	ServerSentMsec  int
  79: }
  80: 
  81: // GameplayPresentationSnapshot returns a receiver-scoped view over the current
  82: // immutable frame and copies only the receiver's pending events.
  83: func (game *Game) GameplayPresentationSnapshot(playerID string) GameplayPresentationSnapshot {
  84: 	game.mu.Lock()
  85: 	frame := game.presentationFrame
  86: 	if frame == nil {
  87: 		game.publishPresentationFrameLocked()
  88: 		frame = game.presentationFrame
  89: 	}
  90: 
  91: 	pending := game.pendingPresentationEvents[playerID]
  92: 	pendingEvents := make([]PendingPresentationEvent, len(pending))
  93: 	copy(pendingEvents, pending)
  94: 	game.mu.Unlock()
  95: 
  96: 	lives := 0
  97: 	if session, ok := frame.playerSessions[playerID]; ok {
  98: 		lives = session.Lives
  99: 	}
 100: 
 101: 	return GameplayPresentationSnapshot{
 102: 		SelfID:          playerID,
 103: 		Lives:           lives,
 104: 		Players:         frame.players,
 105: 		PlayerSessions:  frame.playerSessions,
 106: 		PlayerLifecycle: frame.playerLifecycle,
 107: 		Bullets:         frame.bullets,
 108: 		Asteroids:       frame.asteroids,
 109: 		Pickups:         frame.pickups,
 110: 		TotalAsteroids:  frame.totalAsteroids,
 111: 		PendingEvents:   pendingEvents,
 112: 		ServerSentMsec:  frame.serverSentMsec,
 113: 	}
 114: }
===== services/game-server/internal/protocol/realtime/compact_wire_packet.go =====
   1: package realtime
   2: 
   3: import "github.com/Lokee86/space-rocks/services/game-server/internal/protocol/realtimewire"
   4: 
   5: func CompactWirePacket(packet map[string]any) map[string]any {
   6: 	return compactWirePacketFromDescriptors(packet)
   7: }
   8: 
   9: func compactWireValue(value any, parentKey string) any {
  10: 	switch typed := value.(type) {
  11: 	case map[string]any:
  12: 		expanded := make(map[string]any, len(typed))
  13: 		for key, child := range typed {
  14: 			compactKey := key
  15: 			if mapped, ok := realtimewire.RealtimeWireKeyCompactByReadable["wire."+key]; ok {
  16: 				compactKey = mapped
  17: 			}
  18: 			expanded[compactKey] = compactWireValue(child, key)
  19: 		}
  20: 		return expanded
  21: 	case []any:
  22: 		expanded := make([]any, len(typed))
  23: 		for i := range typed {
  24: 			expanded[i] = compactWireValue(typed[i], parentKey)
  25: 		}
  26: 		return expanded
  27: 	default:
  28: 		if compacted, ok := compactWireValueAlias(parentKey, asString(typed)); ok {
  29: 			return compacted
  30: 		}
  31: 		return value
  32: 	}
  33: }
  34: 
  35: func compactWireValueAlias(parentKey, value string) (string, bool) {
  36: 	var domains []string
  37: 	switch parentKey {
  38: 	case "type":
  39: 		domains = []string{"packet_type", "event_type"}
  40: 	case "lane":
  41: 		domains = []string{"lane"}
  42: 	case "snapshot_kind":
  43: 		domains = []string{"snapshot_kind"}
  44: 	default:
  45: 		return "", false
  46: 	}
  47: 	for _, domain := range domains {
  48: 		if mapping, ok := realtimewire.RealtimeWireValueCompactByReadable[domain]; ok {
  49: 			if compacted, ok := mapping[value]; ok {
  50: 				return compacted, true
  51: 			}
  52: 		}
  53: 	}
  54: 	return "", false
  55: }
  56: 
  57: func asString(value any) string {
  58: 	switch typed := value.(type) {
  59: 	case string:
  60: 		return typed
  61: 	default:
  62: 		return ""
  63: 	}
  64: }

