13: func assembleRealtimeLaneCandidates(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState, sessionState *RealtimeSessionState) (RealtimeLanePlan, error) {
14: 	candidates := make([]RealtimeLaneCandidate, 0, 4)
15: 
16: 	worldCandidates, err := buildWorldLaneCandidates(snapshot, state, sessionState)
17: 	if err != nil {
18: 		return RealtimeLanePlan{}, err
19: 	}
20: 	candidates = append(candidates, worldCandidates...)
21: 
22: 	overlayCandidates, err := buildOverlayLaneCandidates(snapshot, state)
23: 	if err != nil {
24: 		return RealtimeLanePlan{}, err
25: 	}
26: 	candidates = append(candidates, overlayCandidates...)
27: 
28: 	sessionCandidates, err := buildSessionLaneCandidates(snapshot, state)
29: 	if err != nil {
30: 		return RealtimeLanePlan{}, err
31: 	}
32: 	candidates = append(candidates, sessionCandidates...)
33: 	candidates = append(candidates, buildEventLaneCandidates(snapshot, state)...)
34: 	for index := range candidates {
35: 		candidates[index].MatchID = state.MatchID
36: 	}
37: 
38: 	return RealtimeLanePlan{Candidates: candidates}, nil
39: }
40: 
41: func prepareRealtimeSendPlan(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState) (RealtimeSendPrepared, error) {
42: 	state.AdvanceHotLaneTick()
43: 	candidatePlan, err := assembleRealtimeLaneCandidates(snapshot, state, &state)
44: 	if err != nil {
45: 		return RealtimeSendPrepared{}, fmt.Errorf("assemble realtime lane candidates: %w", err)
46: 	}
47: 	candidatePlan.Candidates, err = ExpandRealtimeCandidateChunks(candidatePlan.Candidates)
48: 	if err != nil {
49: 		return RealtimeSendPrepared{}, err
50: 	}
51: 
52: 	records := make([]ScheduleRecord, 0, len(candidatePlan.Candidates))
53: 	for i, candidate := range candidatePlan.Candidates {
54: 		records = append(records, scheduleRecordForCandidate(i, candidate))
55: 	}
56: 
57: 	return RealtimeSendPrepared{
58: 		CandidatePlan: candidatePlan,
59: 		Records:       records,
60: 		SendPlan:      SelectSendPlan(records),
61: 		SessionState:  state,
62: 	}, nil
63: }

