107: func IncludedRealtimeLaneCandidates(candidates []RealtimeLaneCandidate, included []ScheduleRecord) []RealtimeLaneCandidate {
108: 	if len(candidates) == 0 || len(included) == 0 {
109: 		return nil
110: 	}
111: 
112: 	selected := make([]RealtimeLaneCandidate, 0, len(included))
113: 	seen := make(map[int]struct{}, len(included))
114: 	for _, record := range included {
115: 		index := record.CandidateIndex
116: 		if index < 0 || index >= len(candidates) {
117: 			continue
118: 		}
119: 		if _, ok := seen[index]; ok {
120: 			continue
121: 		}
122: 		seen[index] = struct{}{}
123: 		selected = append(selected, candidates[index])
124: 	}
125: 
126: 	if len(selected) == 0 {
127: 		return nil
128: 	}
129: 	return selected
130: }
