 113: func partitionShipUpdates(records []map[string]any) ([]map[string]any, []map[string]any) {
 114: 	hot := make([]map[string]any, 0, len(records))
 115: 	reliable := make([]map[string]any, 0, len(records))
 116: 	for _, record := range records {
 117: 		id := asString(record["id"])
 118: 		if id == "" {
 119: 			continue
 120: 		}
 121: 		hotRecord := map[string]any{"id": id}
 122: 		reliableRecord := map[string]any{"id": id}
 123: 		for key, value := range record {
 124: 			if key == "id" {
 125: 				continue
 126: 			}
 127: 			if _, ok := shipHotUpdateKeys[key]; ok {
 128: 				hotRecord[key] = value
 129: 				continue
 130: 			}
 131: 			reliableRecord[key] = value
 132: 		}
 133: 		if len(hotRecord) > 1 {
 134: 			hot = append(hot, hotRecord)
 135: 		}
 136: 		if len(reliableRecord) > 1 {
 137: 			reliable = append(reliable, reliableRecord)
 138: 		}
 139: 	}
 140: 	return hot, reliable
 141: }
