  41: func appendPlannedRecord(plan *SendPlan, record ScheduleRecord, budget int) int {
  42: 	estimated := record.EstimatedBytes
  43: 	if estimated <= 0 {
  44: 		estimated = EstimatePacketBytes(record.PacketFamily, 1, 0)
  45: 	}
  46: 
  47: 	if isRequiredRecord(record) || isRealHotLaneChunkRecord(record) {
  48: 		plan.Included = append(plan.Included, record)
  49: 		return budget - estimated
  50: 	}
  51: 
  52: 	if budget-estimated >= 0 {
  53: 		plan.Included = append(plan.Included, record)
  54: 		return budget - estimated
  55: 	}
  56: 
  57: 	plan.Deferred = append(plan.Deferred, record)
  58: 	return budget
  59: }
