  56: func estimateJSONIntBytes(value int64) int {
  57: 	if value == 0 {
  58: 		return 1
  59: 	}
  60: 
  61: 	size := 0
  62: 	if value < 0 {
  63: 		size++
  64: 	}
  65: 
  66: 	if value == -9223372036854775808 {
  67: 		return size + len("9223372036854775808")
  68: 	}
  69: 	if value < 0 {
  70: 		value = -value
  71: 	}
  72: 	for value > 0 {
  73: 		size++
  74: 		value /= 10
  75: 	}
  76: 	return size
  77: }
  78: 
  79: func estimateJSONUintBytes(value uint64) int {
  80: 	if value == 0 {
  81: 		return 1
  82: 	}
  83: 	return len(strconv.FormatUint(value, 10))
  84: }
