  86: func estimateJSONStringBytes(value string) int {
  87: 	size := 2 + len(value)
  88: 	for i := 0; i < len(value); i++ {
  89: 		switch value[i] {
  90: 		case '"', '\\':
  91: 			size++
  92: 		case '\b', '\f', '\n', '\r', '\t':
  93: 			size++
  94: 		default:
  95: 			if value[i] < 0x20 {
  96: 				size += 5
  97: 			}
  98: 		}
  99: 	}
 100: 	return size
 101: }
