 103: func estimateCompactShipMovementUpdateBytes(update map[string]any) int {
 104: 	if update == nil {
 105: 		return estimateCompactJSONTupleBytes([]any{compactWireEncodeID("player_id", nil)})
 106: 	}
 107: 
 108: 	id := update["id"]
 109: 	if id == nil {
 110: 		id = update["i"]
 111: 	}
 112: 
 113: 	items := []any{compactWireEncodeID("player_id", id)}
 114: 	values := []struct {
 115: 		readable string
 116: 		compact  string
 117: 	}{
 118: 		{readable: "x", compact: "x"},
 119: 		{readable: "y", compact: "y"},
 120: 		{readable: "rotation", compact: "r"},
 121: 		{readable: "thrusting", compact: "th"},
 122: 	}
 123: 	last := -1
 124: 	resolved := make([]any, len(values))
 125: 	for index, field := range values {
 126: 		value, ok := update[field.readable]
 127: 		if !ok {
 128: 			value, ok = update[field.compact]
 129: 		}
 130: 		if ok {
 131: 			resolved[index] = value
 132: 			last = index
 133: 		}
 134: 	}
 135: 	if last >= 0 {
 136: 		items = append(items, resolved[:last+1]...)
 137: 	}
 138: 	return estimateCompactJSONTupleBytes(items)
 139: }
