 216: func estimateCompactLaneDeltaPacketBytes(packetType string, metadata Metadata, updateField string, updates []map[string]any, updateEstimator func(map[string]any) int) int {
 217: 	size := 2
 218: 	fields := 0
 219: 
 220: 	addField := func(key string, valueBytes int) {
 221: 		if fields > 0 {
 222: 			size++
 223: 		}
 224: 		size += estimateJSONStringBytes(key)
 225: 		size++
 226: 		size += valueBytes
 227: 		fields++
 228: 	}
 229: 
 230: 	addField("t", estimateJSONValueBytes(compactWireValue(packetType, "type")))
 231: 	addField("q", estimateJSONIntBytes(int64(metadata.Sequence)))
 232: 	addField("ms", estimateJSONIntBytes(int64(metadata.ServerSentMsec)))
 233: 	if metadata.MatchID != "" {
 234: 		addField("mid", estimateJSONStringBytes(metadata.MatchID))
 235: 	}
 236: 
 237: 	if metadata.SnapshotKind == SnapshotKind("delta") {
 238: 		if baselineSequence, ok := runtimeBaselineSequence(metadata.Lane, metadata.BaselineID); ok {
 239: 			addField("bq", estimateJSONIntBytes(int64(baselineSequence)))
 240: 		} else if metadata.BaselineID != "" {
 241: 			addField("b", estimateJSONStringBytes(metadata.BaselineID))
 242: 		}
 243: 	} else if metadata.BaselineID != "" && !isRuntimeGeneratedFullBaseline(metadata) {
 244: 		addField("b", estimateJSONStringBytes(metadata.BaselineID))
 245: 	}
 246: 
 247: 	if metadata.ChunkCount > 1 {
 248: 		addField("ci", estimateJSONIntBytes(int64(metadata.ChunkIndex)))
 249: 		addField("cc", estimateJSONIntBytes(int64(metadata.ChunkCount)))
 250: 		if metadata.IsFinalChunk {
 251: 			addField("fc", 4)
 252: 		}
 253: 	}
 254: 
 255: 	arraySize := 2
 256: 	if len(updates) > 0 {
 257: 		arraySize += len(updates) - 1
 258: 		for _, update := range updates {
 259: 			arraySize += updateEstimator(update)
 260: 		}
 261: 	}
 262: 	addField(updateField, arraySize)
 263: 	return size
 264: }

