  21: 	storedWorld, worldHasProjection := state.BaselineProjection(LaneWorld)
  22: 	worldCanUseProjection := worldReady && worldSynced && worldState.IsFinalChunk && worldState.BaselineID != "" && worldHasProjection
  23: 	if !worldCanUseProjection {
