  56: 	}
  57: 
  58: 	candidates := make([]RealtimeLaneCandidate, 0, 4)
  59: 	if shipLifecyclePresent {
  60: 		if candidate, ok := buildShipLifecycleCandidate(worldDelta, state); ok {
