  99: 		packet := ShipWireDeltaPacket{
 100: 			Type:        PacketFamilyShipDelta,
 101: 			Metadata:    nextHotLaneMetadata(currentWorld.Metadata, state, LaneShips),
 102: 			ShipUpdates: shipUpdates,
 103: 		}
 104: 		cohortState.ShipMode = hotLaneModeForChunkCount(shipWireDeltaChunkCount(packet))
 105: 		if hotPacketCadenceAllows(cohortState.ShipMode, state.HotLaneTick) {
 106: 			candidates = append(candidates, mustRealtimeLaneCandidate(packet, currentShips))
 107: 		}
 108: 	} else {
 109: 		cohortState.ShipMode = HotLaneModeInline
 110: 	}
 111: 
 112: 	currentAsteroids := projectAsteroidHotLane(currentWorld)
 113: 	asteroidActive := asteroidHotProjectionIDs(currentAsteroids)
 114: 	assignHotRoutesWithOverride(cohortState.AsteroidRoutes, sortedHotLaneUpdateIDs(asteroidActive), HotUpdateRouteAsteroids)
 115: 	cohortState.RemoveMissingAsteroids(asteroidActive)
 116: 	asteroidUpdates := asteroidHotLaneUpdates(previousAsteroidHotLaneProjection(state, previousWorld), currentAsteroids)
 117: 	if len(asteroidUpdates) > 0 {
 118: 		packet := AsteroidWireDeltaPacket{
 119: 			Type:            PacketFamilyAsteroidDelta,
 120: 			Metadata:        nextHotLaneMetadata(currentWorld.Metadata, state, LaneAsteroids),
 121: 			AsteroidUpdates: asteroidUpdates,
 122: 		}
 123: 		cohortState.AsteroidMode = hotLaneModeForChunkCount(asteroidWireDeltaChunkCount(packet))
 124: 		if hotPacketCadenceAllows(cohortState.AsteroidMode, state.HotLaneTick) {
 125: 			candidates = append(candidates, mustRealtimeLaneCandidate(packet, currentAsteroids))
 126: 		}
 127: 	} else {
 128: 		cohortState.AsteroidMode = HotLaneModeInline
 129: 	}
 130: 
 131: 	currentBullets := projectBulletHotLane(currentWorld)
 132: 	bulletActive := bulletHotProjectionIDs(currentBullets)
 133: 	assignHotRoutesWithOverride(cohortState.BulletRoutes, sortedHotLaneUpdateIDs(bulletActive), HotUpdateRouteBullets)
 134: 	cohortState.RemoveMissingBullets(bulletActive)
 135: 	bulletUpdates := bulletHotLaneUpdates(previousBulletHotLaneProjection(state, previousWorld), currentBullets)
 136: 	if len(bulletUpdates) > 0 {
 137: 		packet := BulletWireDeltaPacket{
 138: 			Type:          PacketFamilyBulletDelta,
 139: 			Metadata:      nextHotLaneMetadata(currentWorld.Metadata, state, LaneBullets),
 140: 			BulletUpdates: bulletUpdates,
 141: 		}
 142: 		cohortState.BulletMode = hotLaneModeForChunkCount(bulletWireDeltaChunkCount(packet))
 143: 		if hotPacketCadenceAllows(cohortState.BulletMode, state.HotLaneTick) {
 144: 			candidates = append(candidates, mustRealtimeLaneCandidate(packet, currentBullets))
 145: 		}
 146: 	} else {
 147: 		cohortState.BulletMode = HotLaneModeInline
 148: 	}
 149: 
 150: 	return candidates, cohortState
 151: }
