 143: func sortedHotLaneUpdateIDs(active map[string]bool) hotLaneSortedUpdateIDs {
 144: 	ids := make(hotLaneSortedUpdateIDs, 0, len(active))
 145: 	for id := range active {
 146: 		ids = append(ids, hotLaneSortedUpdateID{ID: id})
 147: 	}
 148: 	sort.Slice(ids, func(i, j int) bool {
 149: 		return ids[i].ID < ids[j].ID
 150: 	})
 151: 	return ids
 152: }
