 154: func assignHotRoutesWithOverride(routes map[string]HotUpdateRoute, ids hotLaneSortedUpdateIDs, route HotUpdateRoute) {
 155: 	for _, item := range ids {
 156: 		if existing, exists := routes[item.ID]; exists && existing == route {
 157: 			continue
 158: 		}
 159: 		routes[item.ID] = route
 160: 	}
 161: }
