   3: func ExpandRealtimeCandidateChunks(candidates []RealtimeLaneCandidate) ([]RealtimeLaneCandidate, error) {
   4: 	if len(candidates) == 0 {
   5: 		return nil, nil
   6: 	}
   7: 
   8: 	expanded := make([]RealtimeLaneCandidate, 0, len(candidates))
   9: 	for _, candidate := range candidates {
  10: 		chunks, err := expandRealtimeCandidate(candidate)
  11: 		if err != nil {
  12: 			return nil, err
  13: 		}
  14: 		expanded = append(expanded, chunks...)
  15: 	}
  16: 	return expanded, nil
  17: }
  18: 
  19: func expandRealtimeCandidate(candidate RealtimeLaneCandidate) ([]RealtimeLaneCandidate, error) {
  20: 	hardCapChunks, err := expandHardCapCandidate(candidate)
  21: 	if err != nil {
  22: 		return nil, err
  23: 	}
  24: 	if candidate.Kind() == RealtimeLaneCandidateKindFull && candidate.Lane() == LaneWorld {
  25: 		return hardCapChunks, nil
  26: 	}
  27: 	lane, kind := candidate.Lane(), candidate.Kind()
  28: 	if kind != RealtimeLaneCandidateKindDelta {
  29: 		return hardCapChunks, nil
  30: 	}
  31: 
  32: 	switch lane {
  33: 	case LaneShipsLifecycle, LaneBulletsLifecycle, LaneAsteroidsLifecycle:
  34: 		return hardCapChunks, nil
  35: 	case LaneShips:
  36: 		packet, ok := shipWireDeltaPacketFromCandidate(candidate)
  37: 		if !ok {
  38: 			return []RealtimeLaneCandidate{candidate}, nil
  39: 		}
  40: 		packet.Metadata.MatchID = candidate.MatchID
  41: 
  42: 		if shipWireDeltaChunkCount(packet) == 1 {
  43: 			return []RealtimeLaneCandidate{normalizedShipWireDeltaCandidate(candidate, packet, packet.ShipUpdates, 0, 1)}, nil
  44: 		}
  45: 
  46: 		chunkUpdates := greedyShipWireDeltaChunks(packet)
  47: 		if len(chunkUpdates) == 0 {
  48: 			return []RealtimeLaneCandidate{candidate}, nil
  49: 		}
  50: 
  51: 		chunks := make([]RealtimeLaneCandidate, 0, len(chunkUpdates))
  52: 		chunkCount := len(chunkUpdates)
  53: 		for index, updates := range chunkUpdates {
  54: 			chunks = append(chunks, normalizedShipWireDeltaCandidate(candidate, packet, updates, index, chunkCount))
  55: 		}
  56: 		return chunks, nil
  57: 	case LaneBullets:
  58: 		packet, ok := bulletWireDeltaPacketFromCandidate(candidate)
  59: 		if !ok {
  60: 			return []RealtimeLaneCandidate{candidate}, nil
  61: 		}
  62: 		packet.Metadata.MatchID = candidate.MatchID
  63: 
  64: 		if bulletWireDeltaChunkCount(packet) == 1 {
  65: 			return []RealtimeLaneCandidate{normalizedBulletWireDeltaCandidate(candidate, packet, packet.BulletUpdates, 0, 1)}, nil
  66: 		}
  67: 
  68: 		chunkUpdates := greedyBulletWireDeltaChunks(packet)
  69: 		if len(chunkUpdates) == 0 {
  70: 			return []RealtimeLaneCandidate{candidate}, nil
  71: 		}
  72: 
  73: 		chunks := make([]RealtimeLaneCandidate, 0, len(chunkUpdates))
  74: 		chunkCount := len(chunkUpdates)
  75: 		for index, updates := range chunkUpdates {
  76: 			chunks = append(chunks, normalizedBulletWireDeltaCandidate(candidate, packet, updates, index, chunkCount))
  77: 		}
  78: 		return chunks, nil
  79: 	case LaneAsteroids:
  80: 		packet, ok := asteroidWireDeltaPacketFromCandidate(candidate)
  81: 		if !ok {
  82: 			return []RealtimeLaneCandidate{candidate}, nil
  83: 		}
  84: 		packet.Metadata.MatchID = candidate.MatchID
  85: 
  86: 		if !asteroidWireDeltaRequiresChunking(packet) {
  87: 			return []RealtimeLaneCandidate{normalizedAsteroidWireDeltaCandidate(candidate, packet, packet.AsteroidUpdates, 0, 1)}, nil
  88: 		}
  89: 
  90: 		chunkUpdates := greedyAsteroidWireDeltaChunks(packet)
  91: 		if len(chunkUpdates) == 0 {
  92: 			return []RealtimeLaneCandidate{candidate}, nil
  93: 		}
  94: 
  95: 		chunks := make([]RealtimeLaneCandidate, 0, len(chunkUpdates))
  96: 		chunkCount := len(chunkUpdates)
  97: 		for index, updates := range chunkUpdates {
  98: 			chunks = append(chunks, normalizedAsteroidWireDeltaCandidate(candidate, packet, updates, index, chunkCount))
  99: 		}
 100: 		return chunks, nil
 101: 	default:
 102: 		return []RealtimeLaneCandidate{candidate}, nil
 103: 	}
