 106: func shipWireDeltaChunkCount(packet ShipWireDeltaPacket) int {
 107: 	if estimateShipDeltaPacketBytes(packet, packet.ShipUpdates) <= HardCapBytes {
 108: 		return 1
 109: 	}
 110: 	return len(greedyShipWireDeltaChunks(packet))
 111: }
