 113: func hotLaneModeForChunkCount(chunkCount int) HotLaneMode {
 114: 	switch {
 115: 	case chunkCount <= 1:
 116: 		return HotLaneModeFullOwned60Hz
 117: 	case chunkCount == 2:
 118: 		return HotLaneModeFullOwned30Hz
 119: 	case chunkCount == 3:
