   3: func ExpandRealtimeCandidateChunks(candidates []RealtimeLaneCandidate) ([]RealtimeLaneCandidate, error) {
   4: 	if len(candidates) == 0 {
   5: 		return nil, nil
   6: 	}
   7: 
   8: 	expanded := make([]RealtimeLaneCandidate, 0, len(candidates))
   9: 	for _, candidate := range candidates {
  10: 		chunks, err := expandRealtimeCandidate(candidate)
  11: 		if err != nil {
  12: 			return nil, err
  13: 		}
  14: 		expanded = append(expanded, chunks...)
  15: 	}
  16: 	return expanded, nil
  17: }
