  11: func (game *Game) runSimulation() {
  12: 	ticker := time.NewTicker(time.Second / time.Duration(constants.ServerTickRate))
  13: 	defer ticker.Stop()
  14: 
  15: 	delta := 1.0 / float64(constants.ServerTickRate)
  16: 	for {
  17: 		select {
  18: 		case <-game.stopSimulation:
  19: 			return
  20: 		case <-ticker.C:
  21: 			game.Step(delta)
  22: 		}
  23: 	}
  24: }
  25: 
  26: func (game *Game) Step(delta float64) {
  27: 	measure := game.HasRuntimeMeasurements()
  28: 	started := time.Time{}
  29: 	if measure {
  30: 		started = time.Now()
  31: 	}
  32: 
  33: 	var entities measurement.EntityCounts
  34: 	game.mu.Lock()
  35: 	func() {
  36: 		defer game.mu.Unlock()
  37: 		defer game.publishPresentationFrameLocked()
  38: 
  39: 		bounds := space.DefaultBounds()
  40: 
  41: 		game.applyPendingPlayerInputsLocked()
  42: 		game.stepPlayerSessions(delta)
  43: 		if game.isMatchOverLocked() {
  44: 			game.stepPlayers(delta, bounds)
  45: 			game.removeReadyPlayers()
  46: 			game.stepAsteroids(delta, bounds)
  47: 			game.stepBullets(delta, bounds)
  48: 			game.stepPickups(delta)
  49: 			game.stepRadialEffects(delta)
  50: 			for _, observer := range game.simulationStepObservers {
  51: 				observer(delta)
  52: 			}
  53: 		} else {
  54: 			game.stepBots()
  55: 			game.stepPlayerWeapons(delta)
  56: 			game.stepPlayers(delta, bounds)
  57: 			game.removeReadyPlayers()
  58: 			game.stepAsteroidSpawning(delta)
  59: 			game.stepAsteroids(delta, bounds)
  60: 			game.stepBullets(delta, bounds)
  61: 			game.stepPickups(delta)
  62: 			game.stepCollisions()
  63: 			game.stepRadialEffects(delta)
  64: 			for _, observer := range game.simulationStepObservers {
  65: 				observer(delta)
  66: 			}
  67: 		}
  68: 		if measure {
  69: 			entities = game.runtimeMeasurementEntityCountsLocked()
  70: 		}
  71: 	}()
  72: 
  73: 	if measure {
  74: 		game.observeRuntimeMeasurement(time.Since(started), entities)
  75: 	}
  76: }
  77: 
  78: func (game *Game) stepCollisions() {
  79: 	if game.worldSimulationOptions.CanRunCollisions() {
  80: 		game.rebuildAsteroidSpatialIndex()
  81: 		game.handleShipAsteroidCollisions()
  82: 		game.handleBulletAsteroidCollisions()
  83: 		game.rebuildPickupSpatialIndex()
  84: 		game.handlePlayerPickupCollisions()
  85: 	}
  86: }

