 142: func (session *webSocketSession) ensureWebRTCTransport() *WebRTCTransport {
 143: 	if transport := session.webRTCTransportSnapshot(); transport != nil {
 144: 		return transport
 145: 	}
 146: 
 147: 	var peer *WebRTCTransport
 148: 	peer = NewWebRTCTransport(WebRTCSignalHooks{
 149: 		OnLocalICECandidate: func(media string, index int, name string) {
 150: 			if !session.isCurrentWebRTCTransport(peer) {
 151: 				return
 152: 			}
 153: 			session.enqueueWebRTCICECandidate(media, index, name)
 154: 		},
 155: 		OnReady: func() {
 156: 			if !session.isCurrentWebRTCTransport(peer) {
 157: 				return
 158: 			}
 159: 			session.enqueueWebRTCReady()
 160: 			_ = peer.SendSmoke("server-ready", "server smoke peer ready")
 161: 		},
 162: 		OnPacketReceived: func(packet map[string]any, lane string) {
 163: 			if !session.isCurrentWebRTCTransport(peer) {
 164: 				return
 165: 			}
 166: 			if lane == "tooling" {
 167: 				session.handleToolingPacket(packet)
 168: 				return
 169: 			}
 170: 			session.handleWebRTCPacket(packet)
 171: 		},
 172: 		OnChannelClosed: func(lane string) {
 173: 			if !session.isCurrentWebRTCTransport(peer) {
 174: 				return
 175: 			}
 176: 			context := session.sessionContext()
 177: 			bufferedBytes, _ := peer.BufferedAmountForLane(lane)
 178: 			logging.Emit(observability.Request{
 179: 				Event: observability.EventNamePacketRouteFailed,
 180: 				Context: observability.Context{
 181: 					TraceID:   session.connectionTraceID,
 182: 					SessionID: session.sessionID,
 183: 					RoomID:    context.RoomID,
 184: 					PlayerID:  context.GamePlayerID,
 185: 				},
 186: 				Fields: observability.Fields{
 187: 					"error_code":     "webrtc_channel_closed",
 188: 					"failure_mode":   "webrtc_channel_closed",
 189: 					"lane":           lane,
 190: 					"transport":      "webrtc",
 191: 					"buffered_bytes": bufferedBytes,
 192: 				},
 193: 			})
 194: 			if lane == "tooling" {
 195: 				session.closeTooling()
 196: 			}
 197: 			session.clearWebRTCTransportIfCurrent(peer)
 198: 		},
 199: 	})
 200: 	session.mu.Lock()
 201: 	if session.webrtcTransport != nil {
 202: 		transport := session.webrtcTransport
 203: 		session.mu.Unlock()
 204: 		_ = peer.Close()
 205: 		return transport
 206: 	}
 207: 	session.webrtcTransport = peer
 208: 	session.mu.Unlock()
 209: 	return peer
 210: }
