 424: func (session *webSocketSession) toolingContext() toolingrouter.Context {
 425: 	context := session.sessionContext()
 426: 	toolingContext := toolingrouter.Context{
 427: 		SessionID:    session.sessionID,
 428: 		RoomID:       context.RoomID,
 429: 		GamePlayerID: context.GamePlayerID,
 430: 		Room:         context.Room,
 431: 		Capabilities: session.toolingCapabilities,
 432: 	}
 433: 	if context.Room == nil {
 434: 		return toolingContext
 435: 	}
 436: 	gameplayContext := context.Room.GameplayContext()
 437: 	if gameplayContext.Game == nil {
 438: 		return toolingContext
 439: 	}
 440: 	control := game.NewControl(gameplayContext.Game)
 441: 	toolingContext.CommandController = devtools.NewController(devtools.Dependencies{Target: control})
 442: 	return toolingContext
 443: }

