   5: func (game *Game) HandlePacket(playerID string, packet ClientPacket) {
   6: 	if packet.Type == PacketTypeInput {
   7: 		game.enqueuePlayerInput(playerID, packet.Input)
   8: 		return
   9: 	}
  10: 
  11: 	game.mu.Lock()
  12: 	defer game.mu.Unlock()
  13: 
  14: 	if packet.Type == PacketTypeRespawn {
  15: 		game.respawnPlayer(playerID)
  16: 		return
  17: 	}
  18: 	if packet.Type == PacketTypeClientConfig {
  19: 		if _, isBot := game.botControllers[playerID]; isBot {
  20: 			return
  21: 		}
  22: 		if packet.Config.VisibleWorldWidth <= 0 || packet.Config.VisibleWorldHeight <= 0 {
  23: 			return
  24: 		}
  25: 
  26: 		config := runtime.ClampCameraConfig(packet.Config)
  27: 		if session, ok := game.playerSessions[playerID]; ok && session != nil {
  28: 			session.Config = config
  29: 		}
  30: 		if cameraView, ok := game.cameraViews[playerID]; ok && cameraView != nil {
  31: 			cameraView.SetConfig(config)
  32: 		}
  33: 		if player, ok := game.entities.Players[playerID]; ok && player != nil {
  34: 			player.SetConfig(config)
  35: 		}
  36: 		return
  37: 	}
  38: 
  39: 	if _, ok := game.entities.Players[playerID]; !ok {
  40: 		return
  41: 	}
  42: 	if packet.Type == PacketTypePauseRequest {
  43: 		game.togglePlayerPaused(playerID)
  44: 	}
  45: }
