  56: func (game *Game) applyPendingPlayerInputsLocked() {
  57: 	game.inputMu.Lock()
  58: 	pending := game.pendingPlayerInputs
  59: 	game.pendingPlayerInputs = make(map[string]runtime.InputState, len(pending))
  60: 	game.inputMu.Unlock()
  61: 
  62: 	for playerID, input := range pending {
  63: 		player, ok := game.entities.Players[playerID]
  64: 		if !ok || player == nil || !game.playerCanReceiveInput(playerID, player) {
  65: 			continue
  66: 		}
  67: 		player.SetInput(input)
  68: 	}
  69: }

