  10: 
  11: func (index *Index) QueryRect(dst []spatial.Ref, rect spatial.Rect, mask spatial.KindMask) []spatial.Ref {
  12: 	if mask == 0 {
  13: 		return dst
  14: 	}
  15: 
  16: 	rect.Center = space.WrapPosition(rect.Center, index.bounds)
  17: 	rect.HalfExtents.X = math.Max(0, rect.HalfExtents.X)
  18: 	rect.HalfExtents.Y = math.Max(0, rect.HalfExtents.Y)
  19: 	xCells := index.axisRange(rect.Center.X-rect.HalfExtents.X, rect.Center.X+rect.HalfExtents.X, index.bounds.Width, index.cellWidth, index.cellsX)
  20: 	yCells := index.axisRange(rect.Center.Y-rect.HalfExtents.Y, rect.Center.Y+rect.HalfExtents.Y, index.bounds.Height, index.cellHeight, index.cellsY)
  21: 	generation := index.beginQuery()
  22: 
  23: 	for yOffset := 0; yOffset < yCells.count; yOffset++ {
  24: 		y := (yCells.start + yOffset) % index.cellsY
  25: 		for xOffset := 0; xOffset < xCells.count; xOffset++ {
  26: 			x := (xCells.start + xOffset) % index.cellsX
  27: 			for _, entry := range index.buckets[y*index.cellsX+x] {
  28: 				if !mask.Allows(entry.Ref.Kind) || !index.markQueryRef(entry.Ref, generation) {
  29: 					continue
  30: 				}
  31: 				if circleOverlapsRect(rect, entry.Position, entry.Radius, index.bounds) {
  32: 					dst = append(dst, entry.Ref)
  33: 				}
  34: 			}
  35: 		}
  36: 	}
  37: 	return dst
  38: }
  39: 
  40: func circleOverlapsRect(rect spatial.Rect, position physics.Vector2, radius float64, bounds space.Bounds) bool {
  41: 	delta := space.ShortestDelta(rect.Center, position, bounds)
  42: 	distanceX := math.Max(0, math.Abs(delta.X)-rect.HalfExtents.X)
  43: 	distanceY := math.Max(0, math.Abs(delta.Y)-rect.HalfExtents.Y)
  44: 	return distanceX*distanceX+distanceY*distanceY <= radius*radius
  45: }

