  12: func (game *Game) randomAsteroidSpawnPosition(targetView *runtime.CameraView) physics.Vector2 {
  13: 	margin := constants.AsteroidSpawnMargin
  14: 	for attempts := 0; ; attempts++ {
  15: 		spawn := game.randomOffscreenPosition(targetView, margin)
  16: 		if !game.isInsideAsteroidSpawnClearanceForAnyCamera(spawn) {
  17: 			return spawn
  18: 		}
  19: 
  20: 		if attempts > 0 && attempts%16 == 0 {
  21: 			margin += constants.AsteroidSpawnMargin
  22: 		}
  23: 	}
  24: }
  25: 
  26: func (game *Game) randomOffscreenPosition(view *runtime.CameraView, margin float64) physics.Vector2 {
  27: 	width := view.VisibleWorldWidth()
  28: 	height := view.VisibleWorldHeight()
  29: 	left := view.X - width*0.5
  30: 	right := view.X + width*0.5
  31: 	top := view.Y - height*0.5
  32: 	bottom := view.Y + height*0.5
  33: 
  34: 	switch game.rngSource.Intn(4) {
  35: 	case 0:
  36: 		return physics.Vector2{X: game.randomRange(left, right), Y: top - margin}
  37: 	case 1:
  38: 		return physics.Vector2{
  39: 			X: right + margin,
  40: 			Y: game.randomRange(top, bottom),
  41: 		}
  42: 	case 2:
  43: 		return physics.Vector2{
  44: 			X: game.randomRange(left, right),
  45: 			Y: bottom + margin,
  46: 		}
  47: 	default:
  48: 		return physics.Vector2{X: left - margin, Y: game.randomRange(top, bottom)}
  49: 	}
  50: }
