  31: 			b.ReportMetric(float64(scenario.players+scenario.asteroids+scenario.bullets), "entities/snapshot")
  32: 			b.ResetTimer()
  33: 			for i := 0; i < b.N; i++ {
  34: 				_ = game.GameplayPresentationSnapshot("player-0")
  35: 			}
  36: 		})
  37: 	}
  38: }
