  40: func BenchmarkGameplayPresentationFramePublication(b *testing.B) {
  41: 	for _, scenario := range presentationBenchmarkScenarios {
  42: 		b.Run(scenario.name, func(b *testing.B) {
  43: 			game := newPresentationBenchmarkGame(scenario)
  44: 			b.ReportAllocs()
  45: 			b.ResetTimer()
  46: 			for i := 0; i < b.N; i++ {
  47: 				game.mu.Lock()
  48: 				game.publishPresentationFrameLocked()
  49: 				game.mu.Unlock()
  50: 			}
  51: 		})
  52: 	}
  53: }
  54: 
  55: func BenchmarkGameStepWithPresentationSnapshotContention(b *testing.B) {
  56: 	for _, scenario := range presentationBenchmarkScenarios {
  57: 		for _, readers := range []int{0, 1, 4, 8} {
  58: 			b.Run(fmt.Sprintf("%s/%d-readers", scenario.name, readers), func(b *testing.B) {
  59: 				game := newPresentationBenchmarkGame(scenario)
  60: 				game.worldSimulationOptions.SetFreezeWorld(true)
  61: 				var stop atomic.Bool
  62: 				var snapshots atomic.Uint64
  63: 				var wg sync.WaitGroup
  64: 				wg.Add(readers)
  65: 				for i := 0; i < readers; i++ {
  66: 					go func() {
  67: 						defer wg.Done()
  68: 						for !stop.Load() {
  69: 							_ = game.GameplayPresentationSnapshot("player-0")
  70: 							snapshots.Add(1)
  71: 						}
  72: 					}()
  73: 				}
  74: 
  75: 				b.ReportAllocs()
  76: 				b.ReportMetric(float64(scenario.players+scenario.asteroids+scenario.bullets), "entities/step")
  77: 				b.ResetTimer()
  78: 				for i := 0; i < b.N; i++ {
  79: 					game.Step(1.0 / 60.0)
  80: 				}
  81: 				b.StopTimer()
  82: 				stop.Store(true)
  83: 				wg.Wait()
  84: 				b.ReportMetric(float64(snapshots.Load())/float64(b.N), "snapshots/step")
  85: 			})
  86: 		}
  87: 	}
  88: }
  89: 
  90: func newPresentationBenchmarkGame(scenario presentationBenchmarkScenario) *Game {
  91: 	game := New()
  92: 	for i := 0; i < scenario.players; i++ {
  93: 		id := fmt.Sprintf("player-%d", i)
  94: 		session := newPlayerSession(id, physics.Vector2{X: float64(i * 32), Y: float64(i * 32)})
  95: 		game.playerSessions[id] = session
  96: 		game.entities.Players[id] = session.NewShip(session.SpawnPosition)
  97: 	}
  98: 	for i := 0; i < scenario.asteroids; i++ {
  99: 		id := fmt.Sprintf("asteroid-%d", i)
 100: 		game.entities.Asteroids[id] = runtimepkg.NewAsteroid(id, physics.Vector2{X: float64(i), Y: float64(i * 2)}, physics.Vector2{X: 1, Y: -1}, 2, i%3)
 101: 	}
 102: 	for i := 0; i < scenario.bullets; i++ {
 103: 		id := fmt.Sprintf("bullet-%d", i)
 104: 		game.entities.Projectiles[id] = runtimepkg.NewBullet(id, "player-0", physics.Vector2{X: float64(i), Y: float64(i * 2)}, 0, physics.Vector2{X: 2, Y: 0}, 10)
 105: 	}
 106: 	game.mu.Lock()
 107: 	game.publishPresentationFrameLocked()
 108: 	game.mu.Unlock()
 109: 	return game
 110: }

