 135: func (membership *roomMembership) restoreLobbyPlayerIDs() {
 136: 	members := make([]*RoomMember, 0, len(membership.members))
 137: 	for _, member := range membership.members {
 138: 		members = append(members, member)
 139: 	}
 140: 	sort.Slice(members, func(left, right int) bool {
 141: 		leftNumber, leftOK := playerIDNumber(members[left].PlayerID)
 142: 		rightNumber, rightOK := playerIDNumber(members[right].PlayerID)
 143: 		if leftOK != rightOK {
 144: 			return leftOK
 145: 		}
 146: 		if leftOK && leftNumber != rightNumber {
 147: 			return leftNumber < rightNumber
 148: 		}
 149: 		return members[left].MemberID < members[right].MemberID
 150: 	})
 151: 
 152: 	ownerMember := membership.members[membership.ownerID]
 153: 	membership.members = make(map[string]*RoomMember, len(members))
 154: 	membership.ownerID = ""
 155: 	for index, member := range members {
 156: 		playerID := formatPlayerID(index + 1)
 157: 		member.PlayerID = playerID
 158: 		membership.members[playerID] = member
 159: 		if member == ownerMember {
 160: 			membership.ownerID = playerID
 161: 		}
 162: 	}
 163: }
 164: 
 165: func playerIDNumber(playerID string) (int, bool) {
 166: 	number, err := strconv.Atoi(strings.TrimPrefix(strings.ToLower(playerID), "player-"))
 167: 	return number, err == nil && number > 0
 168: }
 169: 
 170: func (membership *roomMembership) nextOwnerID() string {
 171: 	ownerID := ""
 172: 	for remainingPlayerID, member := range membership.members {
 173: 		if member.IsBot {
 174: 			continue
 175: 		}
 176: 		if ownerID == "" || remainingPlayerID < ownerID {
 177: 			ownerID = remainingPlayerID
 178: 		}
 179: 	}
 180: 	return ownerID
 181: }
 182: 
 183: func (membership *roomMembership) occupiedPlayerIDs() map[string]bool {
 184: 	occupied := make(map[string]bool, len(membership.members))
 185: 	for _, member := range membership.members {
 186: 		if member.PlayerID == "" {
 187: 			continue
 188: 		}
 189: 		occupied[member.PlayerID] = true
 190: 	}
 191: 	return occupied
 192: }
 193: 
 194: func (membership *roomMembership) nextAvailablePlayerID() string {
 195: 	occupied := membership.occupiedPlayerIDs()
 196: 	for number := 1; ; number++ {
 197: 		playerID := formatPlayerID(number)
 198: 		if !occupied[playerID] {
 199: 			return playerID
 200: 		}
 201: 	}
 202: }

