   7: )
   8: 
   9: var roomSessions = struct {
  10: 	sync.Mutex
  11: 	byRoom map[*rooms.Room]map[string]*webSocketSession
  12: }{
  13: 	byRoom: make(map[*rooms.Room]map[string]*webSocketSession),
  14: }
  15: 
  16: func addSessionMember(room *rooms.Room, sessionID string, session *webSocketSession) {
  17: 	room.AddMember(rooms.NewRoomMember(sessionID))
  18: 	if accountID := accountIDForSession(session); accountID != "" {
  19: 		room.SetMemberAccountIDForSession(sessionID, accountID)
  20: 	}
  21: 	attachRoomSession(room, sessionID, session)
  22: }
  23: 
  24: func attachRoomSession(room *rooms.Room, sessionID string, session *webSocketSession) {
  25: 	if session == nil {
  26: 		return
  27: 	}
  28: 
  29: 	roomSessions.Lock()
  30: 	defer roomSessions.Unlock()
  31: 
  32: 	sessions := roomSessions.byRoom[room]
  33: 	if sessions == nil {
  34: 		sessions = make(map[string]*webSocketSession)
  35: 		roomSessions.byRoom[room] = sessions
  36: 	}
  37: 	sessions[sessionID] = session
  38: }
  39: 
  40: func detachRoomSession(room *rooms.Room, sessionID string) {
  41: 	roomSessions.Lock()
  42: 	defer roomSessions.Unlock()
  43: 
  44: 	sessions := roomSessions.byRoom[room]
  45: 	if sessions == nil {
  46: 		return
  47: 	}
  48: 	delete(sessions, sessionID)
  49: 	if len(sessions) == 0 {
  50: 		delete(roomSessions.byRoom, room)
  51: 	}
  52: }
  53: 
  54: func snapshotRoomSessions(room *rooms.Room, memberIDs []string) []*webSocketSession {
  55: 	roomSessions.Lock()
  56: 	defer roomSessions.Unlock()
  57: 
  58: 	sessionsByMember := roomSessions.byRoom[room]
  59: 	if sessionsByMember == nil {
  60: 		return nil
  61: 	}
  62: 
  63: 	sessions := make([]*webSocketSession, 0, len(memberIDs))
  64: 	for _, memberID := range memberIDs {
  65: 		if session := sessionsByMember[memberID]; session != nil {
  66: 			sessions = append(sessions, session)
  67: 		}
  68: 	}
  69: 
  70: 	return sessions
  71: }
  72: 
  73: func accountIDForSession(session *webSocketSession) string {
  74: 	if session == nil {
  75: 		return ""
  76: 	}
  77: 
  78: 	identity := session.SessionIdentity()
  79: 	if !identity.IsAuthenticatedAccount() {
  80: 		return ""
  81: 	}
  82: 
  83: 	return identity.AccountID
  84: }

