   9: func quantizeWorldFullPacket(packet WorldFullPacket) (WorldWireFullPacket, error) {
  10: 	quantized := WorldWireFullPacket{
  11: 		Type:      packet.Type,
  12: 		Metadata:  packet.Metadata,
  13: 		Ships:     make([]WorldShipWireRecord, 0, len(packet.Ships)),
  14: 		Bullets:   make([]WorldBulletWireRecord, 0, len(packet.Bullets)),
  15: 		Asteroids: make([]WorldAsteroidWireRecord, 0, len(packet.Asteroids)),
  16: 		Pickups:   make([]WorldPickupWireRecord, 0, len(packet.Pickups)),
  17: 	}
  18: 
  19: 	var err error
  20: 	for _, ship := range packet.Ships {
  21: 		wireShip := WorldShipWireRecord{
  22: 			ID:         ship.ID,
  23: 			ShipType:   ship.ShipType,
  24: 			TeamID:     ship.TeamID,
  25: 			Health:     ship.Health,
  26: 			Shields:    ship.Shields,
  27: 			Thrusting:  ship.Thrusting,
  28: 			TargetKind: ship.TargetKind,
  29: 			TargetID:   ship.TargetID,
  30: 		}
  31: 		wireShip.X, err = quantizeTypedFloat("world.ships.x", ship.X)
  32: 		if err != nil {
  33: 			return WorldWireFullPacket{}, err
  34: 		}
  35: 		wireShip.Y, err = quantizeTypedFloat("world.ships.y", ship.Y)
  36: 		if err != nil {
  37: 			return WorldWireFullPacket{}, err
  38: 		}
  39: 		wireShip.Rotation, err = quantizeTypedFloat("world.ships.rotation", ship.Rotation)
  40: 		if err != nil {
  41: 			return WorldWireFullPacket{}, err
  42: 		}
  43: 		quantized.Ships = append(quantized.Ships, wireShip)
  44: 	}
  45: 
  46: 	for _, bullet := range packet.Bullets {
  47: 		wireBullet := WorldBulletWireRecord{
  48: 			ID:             bullet.ID,
  49: 			OwnerID:        bullet.OwnerID,
  50: 			WeaponID:       bullet.WeaponID,
  51: 			ProjectileType: bullet.ProjectileType,
  52: 		}
  53: 		wireBullet.X, err = quantizeTypedFloat("world.bullets.x", bullet.X)
  54: 		if err != nil {
  55: 			return WorldWireFullPacket{}, err
  56: 		}
  57: 		wireBullet.Y, err = quantizeTypedFloat("world.bullets.y", bullet.Y)
  58: 		if err != nil {
  59: 			return WorldWireFullPacket{}, err
  60: 		}
  61: 		wireBullet.Rotation, err = quantizeTypedFloat("world.bullets.rotation", bullet.Rotation)
  62: 		if err != nil {
  63: 			return WorldWireFullPacket{}, err
  64: 		}
  65: 		quantized.Bullets = append(quantized.Bullets, wireBullet)
  66: 	}
  67: 
  68: 	for _, asteroid := range packet.Asteroids {
  69: 		wireAsteroid := WorldAsteroidWireRecord{
  70: 			ID:      asteroid.ID,
  71: 			Size:    asteroid.Size,
  72: 			Health:  asteroid.Health,
  73: 			Variant: asteroid.Variant,
  74: 		}
  75: 		wireAsteroid.X, err = quantizeTypedFloat("world.asteroids.x", asteroid.X)
  76: 		if err != nil {
  77: 			return WorldWireFullPacket{}, err
  78: 		}
  79: 		wireAsteroid.Y, err = quantizeTypedFloat("world.asteroids.y", asteroid.Y)
  80: 		if err != nil {
  81: 			return WorldWireFullPacket{}, err
  82: 		}
  83: 		wireAsteroid.Scale, err = quantizeTypedFloat("world.asteroids.scale", asteroid.Scale)
  84: 		if err != nil {
  85: 			return WorldWireFullPacket{}, err
  86: 		}
  87: 		quantized.Asteroids = append(quantized.Asteroids, wireAsteroid)
  88: 	}
  89: 
  90: 	for _, pickup := range packet.Pickups {
  91: 		wirePickup := WorldPickupWireRecord{
  92: 			ID:              pickup.ID,
  93: 			Type:            pickup.Type,
  94: 			PickupClass:     pickup.PickupClass,
  95: 			Health:          pickup.Health,
  96: 			AgeSeconds:      0,
  97: 			LifespanSeconds: 0,
  98: 		}
  99: 		wirePickup.X, err = quantizeTypedFloat("world.pickups.x", pickup.X)
 100: 		if err != nil {
 101: 			return WorldWireFullPacket{}, err
 102: 		}
 103: 		wirePickup.Y, err = quantizeTypedFloat("world.pickups.y", pickup.Y)
 104: 		if err != nil {
 105: 			return WorldWireFullPacket{}, err
 106: 		}
 107: 		wirePickup.AgeSeconds, err = quantizeTypedFloat("world.pickups.age_seconds", pickup.AgeSeconds)
 108: 		if err != nil {
 109: 			return WorldWireFullPacket{}, err
 110: 		}
 111: 		wirePickup.LifespanSeconds, err = quantizeTypedFloat("world.pickups.lifespan_seconds", pickup.LifespanSeconds)
 112: 		if err != nil {
 113: 			return WorldWireFullPacket{}, err
 114: 		}
 115: 		quantized.Pickups = append(quantized.Pickups, wirePickup)
 116: 	}
 117: 
 118: 	return quantized, nil
 119: }
 120: 
 121: func quantizeTypedFloat(fieldPath string, value float64) (int64, error) {
 122: 	policy, ok := quantize.LookupPolicy(fieldPath)
 123: 	if !ok {
 124: 		return 0, fmt.Errorf("quantize %s: missing policy", fieldPath)
 125: 	}
 126: 	encoded, err := quantize.EncodeFloat(policy, value)
 127: 	if err != nil {
 128: 		return 0, err
 129: 	}
 130: 	return encoded, nil
 131: }

