  76: func CompareLaneRecordFields[T any](previous []T, current []T, recordID func(T) string, identityWireKey string) FieldRecordDelta[T] {
  77: 	previousByID := make(map[string]T, len(previous))
  78: 	for _, record := range previous {
  79: 		previousByID[recordID(record)] = record
  80: 	}
  81: 
  82: 	currentByID := make(map[string]T, len(current))
  83: 	currentIDs := make([]string, 0, len(current))
  84: 	for _, record := range current {
  85: 		id := recordID(record)
  86: 		currentByID[id] = record
  87: 		currentIDs = append(currentIDs, id)
  88: 	}
  89: 	sort.Strings(currentIDs)
  90: 
  91: 	previousIDs := make([]string, 0, len(previous))
  92: 	for _, record := range previous {
  93: 		previousIDs = append(previousIDs, recordID(record))
  94: 	}
  95: 	sort.Strings(previousIDs)
  96: 
  97: 	delta := FieldRecordDelta[T]{}
  98: 
  99: 	for _, id := range currentIDs {
 100: 		currentRecord := currentByID[id]
 101: 		previousRecord, ok := previousByID[id]
 102: 		if !ok {
 103: 			delta.Creates = append(delta.Creates, currentRecord)
 104: 			continue
 105: 		}
 106: 
 107: 		previousWire := wireStructToMap(previousRecord)
 108: 		currentWire := wireStructToMap(currentRecord)
 109: 		update := map[string]any{identityWireKey: currentWire[identityWireKey]}
 110: 		if update[identityWireKey] == nil {
 111: 			update[identityWireKey] = recordID(currentRecord)
 112: 		}
 113: 
 114: 		for key, currentValue := range currentWire {
 115: 			if key == identityWireKey {
 116: 				continue
 117: 			}
 118: 			if !reflect.DeepEqual(previousWire[key], currentValue) {
 119: 				update[key] = currentValue
 120: 			}
 121: 		}
 122: 
 123: 		if len(update) > 1 {
 124: 			delta.Updates = append(delta.Updates, update)
 125: 		}
 126: 	}
 127: 
 128: 	for _, id := range previousIDs {
 129: 		if _, ok := currentByID[id]; !ok {
 130: 			delta.Deletes = append(delta.Deletes, id)
 131: 		}
 132: 	}
 133: 
 134: 	return delta
 135: }
